import csv,json,math,os
with open('market.csv',newline='') as f: rows=list(csv.DictReader(f))
base=json.load(open('memory/baseline_forecasts.json'))
today=json.load(open('predictions/2026-04-25.json'))
over={x['question_id']:x['outcomes'] for x in today}
active={x['qid']:x for x in rows if x['is_resolved'].strip().lower()=='false'}
resolved={x['qid']:x for x in rows if x['is_resolved'].strip().lower()=='true'}
errs=[]
if len(rows)"'!=378 or len(active)!=292 or len(resolved)!=86: errs.append(f'"'counts {len(rows)}/{len(active)}/{len(resolved)}')
for q,o in over.items():
 if q not in active: errs.append(f'today inactive {q}')
 if len(o)>5: errs.append(f'too many {q}')
 s=sum(o.values())
 if s>1+1e-12 or s<0: errs.append(f'bad sum {q} {s}')
 for k,v in o.items():
  if k.strip().lower() in {'unknown','tbd','other','n/a'}: errs.append(f'placeholder {q} {k}')
  if not isinstance(v,(int,float)) or v<0 or v>1: errs.append(f'bad prob {q} {k} {v}')
for q,x in active.items():
 if q not in base: errs.append(f'missing baseline {q}'); continue
 try: market_pred=json.loads(x['my_prediction']) if x['my_prediction'].strip() else None
 except Exception as e: errs.append(f'bad market json {q}: {e}'); continue
 expected=over.get(q,market_pred)
 if not expected: errs.append(f'no active forecast {q}')
 if base[q]"'!=expected: errs.append(f'"'baseline mismatch {q}: {base[q]} "'!= {expected}'"')
print(f'rows={len(rows)} active={len(active)} resolved={len(resolved)} today={len(today)} baseline={len(base)}')
print('today sums:', {q:round(sum(o.values()),6) for q,o in over.items()})
print('validation:', 'PASS' if not errs else 'FAIL')
for e in errs[:30]: print('ERROR',e)
if len(errs)>30: print('... plus',len(errs)-30)
PY"

